      "@type": "Question",
      "name": "Do you teach both Cambridge and Edexcel A-Level Maths?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. The exact specification, component choices, notation and paper structure are confirmed before resources and practice are selected."
      }
    },
    {
      "@type": "Question",
      "name": "Do you support both AS and A2?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. AS foundations and A2 progression are taught at the appropriate depth, with prerequisite repair included when later topics expose an earlier gap."
      }
    },
    {
      "@type": "Question",
      "name": "Which applied components do you teach?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Support can include statistics and mechanics where they form part of the student’s specification, alongside the required pure mathematics."
      }
    },
    {
      "@type": "Question",
      "name": "Are past papers included?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Topic questions, timed components and full papers are introduced progressively and reviewed with the relevant board’s mark-scheme conventions."
      }
    },
    {
      "@type": "Question",
      "name": "Can tuition be taken online?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Online support can be considered for A-Level students, subject to the diagnostic, timetable and suitability of the requested component and level."
      }
    }
  ]
}

