{
      "@context":"https://schema.org",
      "@type":"FAQPage",
      "mainEntity":[
        {"@type":"Question","name":"What's the difference between AS and full A Level in Cambridge Maths 9709?","acceptedAnswer":{"@type":"Answer","text":"AS involves two components (e.g., Paper 1 + Paper 4 or Paper 1 + Paper 5). A Level requires four components, including Paper 1 and Paper 3 plus additional Mechanics/Statistics papers depending on the route chosen."}},
        {"@type":"Question","name":"What are the 9709 paper timings and marks?","acceptedAnswer":{"@type":"Answer","text":"Paper 1 is 1h50 (75 marks), Paper 3 is 1h50 (75 marks), and Papers 2/4/5/6 are each 1h15 (50 marks). Paper 2 is AS-only."}},
        {"@type":"Question","name":"Why do students struggle with A Level Mechanics?","acceptedAnswer":{"@type":"Answer","text":"Many rely on memorized formulas without diagram and force reasoning. Cambridge questions reward correct modelling and method steps, so we train from free-body diagrams and structured setup."}},
        {"@type":"Question","name":"What is the exam structure for Cambridge Physics 9702?","acceptedAnswer":{"@type":"Answer","text":"It includes Paper 1 MCQ (1h15), Paper 2 structured (1h15), Paper 3 practical (2h), Paper 4 A Level structured (2h), and Paper 5 planning/analysis (1h15)."}},
        {"@type":"Question","name":"Do you help with Cambridge practical skills (Paper 3 / Paper 5)?","acceptedAnswer":{"@type":"Answer","text":"Yes. We practice planning, data tables, graphing conventions, uncertainties, and evaluation because those papers test experimental thinking, not just theory."}},
        {"@type":"Question","name":"Can A Level tuition be done online effectively?","acceptedAnswer":{"@type":"Answer","text":"Yes — if written working is checked live. We use real-time correction via WhatsApp photo submissions during class so every step is verified."}},
        {"@type":"Question","name":"How do we start at Ankuram?","acceptedAnswer":{"@type":"Answer","text":"Start with a 60-minute diagnostic assessment (₹750) so we can identify gaps and decide the right paper-focused plan."}}
      ]
    }

